tools.example:
data = Table[{x, 3 + 2 x + RandomVariate[NormalDistribution[0, 0.5]]}, {x, 0, 10, 0.2}];
lm = LinearModelFit[data, x, x];
{lm["BestFit"], lm["RSquared"], lm["ParameterTable"]}

data = Table[{t, 5 Exp[-0.4 t] + RandomVariate[NormalDistribution[0, 0.1]]},
  {t, 0, 10, 0.25}];
nlm = NonlinearModelFit[data, a Exp[-b t], {{a, 4}, {b, 0.5}}, t];
{nlm["BestFitParameters"], nlm["ParameterConfidenceIntervalTable"]}

data = Table[{x, If[RandomReal[] < 1/(1 + Exp[-(x - 5)]), 1, 0]}, {x, 0, 10, 0.1}];
glm = GeneralizedLinearModelFit[data, x, x,
  ExponentialFamily -> "Binomial", LinkFunction -> "Logit"];
glm["ParameterTable"]

data = Table[{x, Boole[RandomReal[] < 1/(1 + Exp[-(x - 3)])]}, {x, 0, 6, 0.05}];
lmf = LogitModelFit[data, x, x];
Plot[lmf[x], {x, 0, 6}]

data = Table[{x, Boole[RandomReal[] < CDF[NormalDistribution[3, 1], x]]},
  {x, 0, 6, 0.05}];
ProbitModelFit[data, x, x]["ParameterTable"]

a = RandomVariate[NormalDistribution[], 200];
b = RandomVariate[StudentTDistribution[3], 200];
KolmogorovSmirnovTest[a, b]

a = RandomVariate[NormalDistribution[0, 1], 100];
b = RandomVariate[NormalDistribution[0.4, 1], 100];
LocationTest[{a, b}, 0, "TestDataTable"]

a = RandomVariate[NormalDistribution[0, 1], 100];
b = RandomVariate[NormalDistribution[0, 2], 100];
VarianceTest[{a, b}]

x = RandomVariate[NormalDistribution[], 200];
y = 0.5 x + RandomVariate[NormalDistribution[], 200];
IndependenceTest[x, y]

x = Range[50];
y = Exp[x/20] + RandomVariate[NormalDistribution[0, 0.5], 50];
SpearmanRankTest[x, y]
